"use client";

import { Chip } from "@/components/base/badges/chip";

const COLORS = [
  "orange",
  "lime",
  "rose",
  "yellow",
  "cyan",
  "blue",
  "purple",
  "neutral",
  "gray",
  "soft",
] as const;
const REFERENCE_COLORS = ["lime", "rose", "yellow", "cyan", "neutral", "gray", "soft"] as const;

export default function ChipDemo() {
  return (
    <div className="flex flex-col gap-6">
      <div className="flex flex-wrap items-center justify-center gap-3">
        <Chip variant="bold" color="lime">
          +12.5%
        </Chip>
        <Chip variant="subtle" color="cyan">
          $3.252
        </Chip>
        <Chip variant="caption" color="rose">
          Backend Engineer
        </Chip>
      </div>

      <div className="flex flex-wrap items-center gap-3">
        {COLORS.map((color) => (
          <Chip key={color} variant="bold" color={color}>
            {color}
          </Chip>
        ))}
      </div>
      <div className="flex flex-col gap-5">
        {(["bold", "subtle", "caption"] as const).map((variant) => (
          <div
            key={variant}
            data-palette={variant}
            className="flex flex-wrap items-center justify-center gap-3"
          >
            {REFERENCE_COLORS.map((color) => (
              <Chip key={color} variant={variant} color={color}>
                {variant === "bold" ? color : variant === "subtle" ? "$3.252" : "Backend Engineer"}
              </Chip>
            ))}
          </div>
        ))}
      </div>
    </div>
  );
}

